def find_minimal_edit(s_in, s_out):
    """Find the minimal edit that transforms s_in to s_out"""
    # Simple approach: find first difference and determine what needs to be changed
    min_len = min(len(s_in), len(s_out))

    # Find first position where they differ
    pos = 0
    while pos < min_len and s_in[pos] == s_out[pos]:
        pos += 1

    # If we've reached the end of one string, it's an insertion/deletion
    if pos == min_len:
        if len(s_in) < len(s_out):
            # Insertion at the end
            return ("", s_out[pos:], pos)
        else:
            # Deletion at the end
            return (s_in[pos:], "", pos)

    # Find where the rest of the strings match
    # We need to find the smallest substring that needs to be replaced
    # For simplicity, let's check if we're replacing a substring or inserting

    # Try to find longest common prefix/suffix to understand the edit better
    # Let's do a simpler approach for now
    if len(s_in) > len(s_out):
        # Deletion case
        for i in range(len(s_in)):
            if i >= len(s_out) or s_in[i] != s_out[i]:
                # Remove s_in[i] and see if remaining matches
                remaining_in = s_in[:i] + s_in[i+1:]
                if remaining_in == s_out:
                    return (s_in[i], "", i)
                break
    elif len(s_in) < len(s_out):
        # Insertion case
        for i in range(len(s_in) + 1):
            if i >= len(s_out) or s_in[i] != s_out[i]:
                # Insert s_out[i] at position i
                return ("", s_out[i], i)
                break
    else:
        # Same length, find the first difference
        for i in range(len(s_in)):
            if s_in[i] != s_out[i]:
                return (s_in[i], s_out[i], i)

    return ("", "", 0)  # Default case

# Test with our changed pairs
changed = [(0, 'fba', 'fbcf'), (1, 'avx', 'cfvy'), (2, 'hcga', 'hcgcf'), (3, 'vviuc', 'vvgiduc')]

for idx, inp, outp in changed:
    old_sub, new_sub, pos = find_minimal_edit(inp, outp)
    print(f"Pair {idx}: '{inp}' → '{outp}' | Change: '{old_sub}' → '{new_sub}' at pos {pos}")

